#[test]
fn pounds_mass_per_pound_force_hour() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x * 1000.0 / (9.80665e-3 * 3600.0);
        assert_close(
            SpecificFuelConsumption::from_pounds_mass_per_pound_force_hour(v).as_base(),
            base,
            F64_TOL,
        );
        let x: f64 = base;
        let back = x * 9.80665e-3 * 3600.0 / 1000.0;
        assert_close(
            SpecificFuelConsumption::from_base(base).as_pounds_mass_per_pound_force_hour(),
            back,
            F64_TOL,
        );
        assert_close(
            SpecificFuelConsumption::from_pounds_mass_per_pound_force_hour(v)
                .as_pounds_mass_per_pound_force_hour(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            SpecificFuelConsumption::from_pounds_mass_per_pound_force_hour(v as f32).as_base()
                as f64,
            base,
            F32_TOL,
        );
        assert_close(
            SpecificFuelConsumption::from_base(base as f32).as_pounds_mass_per_pound_force_hour()
                as f64,
            back,
            F32_TOL,
        );
    }
}

