#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        SpecificFuelConsumption::new(v, SpecificFuelConsumptionUnit::PoundMassPerPoundForceHour),
        SpecificFuelConsumption::from_pounds_mass_per_pound_force_hour(v)
    );
    assert_eq!(
        SpecificFuelConsumption::from_base(v)
            .convert_to(SpecificFuelConsumptionUnit::PoundMassPerPoundForceHour),
        SpecificFuelConsumption::from_base(v).as_pounds_mass_per_pound_force_hour()
    );
    assert_eq!(
        SpecificFuelConsumption::new(v, SpecificFuelConsumptionUnit::KilogramPerKilogramForceHour),
        SpecificFuelConsumption::from_kilograms_per_kilogram_force_hour(v)
    );
    assert_eq!(
        SpecificFuelConsumption::from_base(v)
            .convert_to(SpecificFuelConsumptionUnit::KilogramPerKilogramForceHour),
        SpecificFuelConsumption::from_base(v).as_kilograms_per_kilogram_force_hour()
    );
    assert_eq!(
        SpecificFuelConsumption::new(v, SpecificFuelConsumptionUnit::GramPerKilonewtonSecond),
        SpecificFuelConsumption::from_grams_per_kilonewton_second(v)
    );
    assert_eq!(
        SpecificFuelConsumption::from_base(v)
            .convert_to(SpecificFuelConsumptionUnit::GramPerKilonewtonSecond),
        SpecificFuelConsumption::from_base(v).as_grams_per_kilonewton_second()
    );
    assert_eq!(
        SpecificFuelConsumption::new(v, SpecificFuelConsumptionUnit::KilogramPerKilonewtonSecond),
        SpecificFuelConsumption::from_kilograms_per_kilonewton_second(v)
    );
    assert_eq!(
        SpecificFuelConsumption::from_base(v)
            .convert_to(SpecificFuelConsumptionUnit::KilogramPerKilonewtonSecond),
        SpecificFuelConsumption::from_base(v).as_kilograms_per_kilonewton_second()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = SpecificFuelConsumption::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            SpecificFuelConsumption::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in SpecificFuelConsumptionUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        SpecificFuelConsumption::from_base(0.0).auto_unit().unit,
        SpecificFuelConsumptionUnit::GramPerKilonewtonSecond
    );
}

